  "// Pulses. variant: 0 radar rings, 1 breathing halo, 2 heartbeat, 3 ping (travels A -> along dir), 4 tap ripple.\n// c0 colour, c1 hot/core colour\n// p0 (count, period, reach, width)\n// p1 (intensity, t0, duration, repeat)    t0/duration/repeat: one-shots (ping, ripple)\n// p2 (travel, lag, head radius, occlusion)\n// aux: origin xy, direction xy (ping) | origin xy (ripple)\n\n// Ease with anticipation for the ping: cubic B\u00e9zier in value, P1 < 0 winds up against the travel,\n// P2 = 1 lands with zero velocity (decelerates in, never stops dead).\nfn shoot(u: f32) -> f32 {\n    let x = clamp(u, 0.0, 1.0);\n    let m = 1.0 - x;\n    return 3.0 * m * m * x * (-0.12) + 3.0 * m * x * x * 1.0 + x * x * x;\n}\nfn beat_env(x: f32) -> f32 {\n    // Fast attack, exponential release; continuous at the peak.\n    return select(exp(-x / 0.085), exp(-(x / 0.018) * (x / 0.018)), x < 0.0);\n}\n\n// One ping shot at `age` seconds: (energy, white-hot share).\nfn ping(c: Ctx, i: Inst, age: f32, dur: f32) -> vec2f {\n    let o = i.aux.xy;\n    let dir = normalize(i.aux.zw);\n    let travel = i.p2.x;\n    let head_r = i.p2.z;\n    if (age < 0.0) { return vec2f(0.0); }\n    let u = age / dur;\n    if (c.reduced) {\n        // No travel: the destination glows up and cools in place.\n        let dest = o + dir * travel;\n        let env = smoothstep(0.0, 0.2, age) * exp(-max(age - 0.2, 0.0) * 3.0);\n        return vec2f(env * gauss(length(c.p - dest), head_r * 3.0), 0.0);\n    }\n    let s_head = shoot(u);\n    let s_tail = shoot(u - i.p2.y);\n    let hpos = o + dir * travel * s_head;\n    let tpos = o + dir * travel * s_tail;\n    let sd = segdist(c.p, tpos, hpos);\n    // After arrival the head blooms out and cools (continuous at u = 1).\n    let after = max(u - 1.0, 0.0);\n    let cool = exp(-after * 3.5);\n    let hr = head_r * (1.0 + 0.9 * (1.0 - cool));\n    let tailw = head_r * 0.55 * (0.35 + 0.65 * sd.y);\n    let tail = gauss(sd.x, tailw) * sd.y * sd.y * 0.8;\n    let dh = length(c.p - hpos);\n    let head = gauss(dh, hr) + 0.35 * bloom(dh - hr * 0.5, hr * 1.2, hr * 8.0);\n    var e = (head + tail) * cool;\n    let hot = gauss(dh, hr * 0.45) * cool * cool;\n    // Launch flash at the origin.\n    let fr = 26.0 * (1.0 - exp(-age * 7.0));\n    e += exp(-age * 10.0) * smoothstep(0.0, 0.03, age) * gauss(length(c.p - o) - fr, 2.0 + age * 6.0) * 0.5;\n    return vec2f(e, hot);\n}\n\nfn rune_shade(in: VOut) -> vec4f {\n    let i = inst_at();\n    let c = ctx(i, in.px);\n    let n = i32(i.p0.x + 0.5);\n    let period = max(i.p0.y, 0.05);\n    let reach = i.p0.z;\n    let width = i.p0.w;\n    let inten = i.p1.x;\n    let occl = select(1.0, i.p2.w, effective_blend_mode(i) == 0u);\n    let outside = smoothstep(-c.aa, c.aa, c.d);\n    var e = 0.0;     // emitted energy (tint)\n    var hotv = 0.0;  // white-hot share\n\n    if (c.variant == 0) {\n        if (c.reduced) {\n            e = 0.35 * bloom(c.d, reach * 0.18, reach * 0.8);\n        } else {\n            for (var k = 0; k < n; k++) {\n                let ph = fract(c.t / period + f32(k) / f32(n));\n                let r = reach * (1.0 - pow(1.0 - ph, 2.2));\n                let w = width * (1.0 + 2.2 * ph);\n                let a = pow(1.0 - ph, 1.6) * smoothstep(0.0, 0.08, ph);\n                let ring = gauss(c.d - r, w);\n                // Faint wash trailing inside the ring front, like a radar sweep.\n                let wash = smoothstep(r + w, r - w, c.d) * exp(-(r - c.d) / max(reach * 0.22, 1.0));\n                e += a * (ring + 0.22 * wash);\n            }\n            e += 0.18 * bloom(c.d, reach * 0.1, reach * 0.6);\n        }\n        e *= outside;\n    } else if (c.variant == 1) {\n        var b = 0.5;\n        if (!c.reduced) { b = 0.5 - 0.5 * cos(TAU * c.t / period); b = b * b * (3.0 - 2.0 * b); }\n        let r = reach * (0.55 + 0.45 * b);\n        e = (0.45 + 0.55 * b) * bloom(c.d, r, r * 5.0) * outside;\n        hotv = 0.25 * b * gauss(max(c.d, 0.0), r * 0.25);\n    } else if (c.variant == 2) {\n        var beat = 0.3;\n        var ring = 0.0;\n        if (!c.reduced) {\n            // Every beat is its own instance: the rings of earlier beats keep expanding and fading\n            // under the new one instead of being cut when it starts.\n            let tp = c.t / period;\n            let kb = floor(tp);\n            beat = 0.0;\n            for (var k = -1; k < 3; k++) {\n                let x = tp - (kb - f32(k));\n                beat += beat_env(x) + 0.62 * beat_env(x - 0.17);\n                let age = x * period; // seconds since that beat's lub\n                if (age > 0.0) {\n                    let rr = reach * (1.0 - exp(-age * 4.5));\n                    // Finished rings fade out instead of piling up into a band at full reach.\n                    ring += exp(-age * 3.2) * smoothstep(0.0, 0.03, age) * (1.0 - smoothstep(0.7, 1.3, age)) * gauss(c.d - rr, width * (1.0 + age * 3.0));\n                }\n            }\n            // Fade the faint tail of old rings out before the quad edge.\n            let edge = reach + width * 16.0;\n            ring *= 1.0 - smoothstep(edge * 0.8, edge, c.d);\n        }\n        let r = reach * 0.22 * (1.0 + 0.35 * beat);\n        e = ((0.25 + 0.75 * beat) * bloom(c.d, r, reach) + 0.55 * ring) * outside;\n        hotv = 0.35 * beat * gauss(max(c.d, 0.0), r * 0.25) * outside;\n    } else if (c.variant == 3) {\n        let dur = max(i.p1.z, 0.05);\n        let age0 = c.t - i.p1.y;\n        // A repeating ping lets the previous shot finish blooming while the next one flies.\n        var shots = 1;\n        var age = age0;\n        if (i.p1.w > 0.0 && age0 > 0.0) {\n            age = age0 - floor(age0 / i.p1.w) * i.p1.w;\n            shots = 3;\n        }\n        for (var k = 0; k < shots; k++) {\n            let a = age + f32(k) * i.p1.w;\n            // PING_LIFE in pack.rs: the frame loop ticks until the last shot ends here.\n            if (a > age0 + 1e-4 || a > dur * 2.2) { break; }\n            let pe = ping(c, i, a, dur);\n            e += pe.x;\n            hotv += pe.y;\n        }\n    } else {\n        // Ripple from a tap point, confined to the shape with a soft edge.\n        let dur = max(i.p1.z, 0.05);\n        let age = c.t - i.p1.y;\n        if (age >= 0.0 && age < dur) {\n            let u = age / dur;\n            let r = length(c.p - i.aux.xy);\n            let inside = smoothstep(c.aa, -c.aa, c.d);\n            if (c.reduced) {\n                e = 0.06 * (1.0 - u) * smoothstep(0.0, 0.08, u) * inside;\n            } else {\n                let rr = reach * (1.0 - pow(1.0 - u, 3.0));\n                let w = width * (1.0 + 3.0 * u);\n                let fade = pow(1.0 - u, 1.5);\n                let ring = gauss(r - rr, w) * fade * 0.55;\n                let fill = smoothstep(rr + w, rr - w * 3.0, r) * 0.05 * (1.0 - u) * (1.0 - u) * smoothstep(0.0, 0.05, u);\n                e = (ring * 0.7 + fill) * inside;\n                hotv = ring * 0.1 * inside;\n            }\n        }\n    }\n    let col = i.c0.rgb * e + i.c1.rgb * hotv;\n    return finish(vec4f(col * inten, (e + hotv) * occl * inten), in.px);\n}\n";
export const ELECTRIC =
  COMMON +
  "// Electricity. variant: 0 arc A -> B, 1 around the border, 2 charged border (calm UI variant).\n// Bolt paths, crawl and forks are CPU tables (cpu.rs::electric); the shader only measures distance\n// to them and lights it. xf = (first, N samples, forks, strands).\n// c0 glow tint, c1 hot core, c2 cooled fork colour\n// p0 (amplitude pt, frequency cells/100pt, speed, core width pt)\n// p1 (intensity, glow radius pt, fork rate 0..1, flicker 0..1)\n// p2 (strands, gap pt (border offset), fork length pt, occlusion)\n// aux: A xy, B xy (arc)\n\nstruct Bolt { core: f32, halo: f32 }\n\nfn shade_bolt(dist: f32, w: f32, gr: f32) -> Bolt {\n    var b: Bolt;\n    b.core = gauss(dist, w);\n    let o = dist / gr;\n    // A narrow coloured sheath plus a faint 1/(1+d^2) tail: the air right around the channel glows,\n    // not a wide haze.\n    b.halo = 0.35 / (1.0 + o * o) * (1.0 - smoothstep(gr * 2.5, gr * 5.0, dist)) + 0.65 * gauss(dist, gr * 0.6);\n    return b;\n}\n// Lateral distance to a sampled path, slope-corrected but capped so steep jags never smear\n// into streaks.\nfn lat(dv: f32, a: f32, b: f32, step: f32) -> f32 {\n    let s = (b - a) / step;\n    // Near field: perpendicular distance to the local segment. Far field: the plain lateral offset\n    // (already a good distance there), so the halo never streaks along steep jags.\n    let k = inverseSqrt(1.0 + min(s * s, 3.0));\n    return dv * mix(k, 1.0, smoothstep(1.5, 8.0, abs(dv)));\n}\nfn fork_col(i: Inst, heat: f32) -> vec3f {\n    return mix(mix(i.c2.rgb, i.c0.rgb, smoothstep(0.0, 0.5, heat)), i.c1.rgb, smoothstep(0.6, 1.0, heat));\n}\n\nfn rune_shade(in: VOut) -> vec4f {\n    let i = inst_at();\n    let c = ctx(i, in.px);\n    let w = max(i.p0.w, c.aa * 0.7);\n    let inten = i.p1.x;\n    let gr = max(i.p1.y, 1e-3);\n    let gap = i.p2.y;\n    let first = u32(i.xf.x);\n    let n = u32(i.xf.y);\n    let nf = u32(i.xf.z);\n    let ns = u32(i.xf.w);\n    let q4 = n >> 2u;\n    let fl = shader_data_at(first + 1u);\n    let base = first + 2u;\n\n    var core = 0.0;\n    var halo = 0.0;\n    var fork_hot = vec3f(0.0);\n\n    if (c.variant == 0) {\n        let a = i.aux.xy;\n        let bb = i.aux.zw;\n        let L = max(length(bb - a), 1.0);\n        let dir = (bb - a) / L;\n        let nrm = vec2f(-dir.y, dir.x);\n        let rel = c.p - a;\n        let u = dot(rel, dir) / L;\n        let v = dot(rel, nrm);\n        let uc = clamp(u, 0.0, 1.0);\n        let fi = uc * f32(n - 1u);\n        let i0 = min(u32(fi), n - 2u);\n        let f = fi - f32(i0);\n        let step = L / f32(n - 1u);\n        for (var k = 0u; k < ns; k++) {\n            let sb = base + k * q4;\n            let d0 = dat1(sb, i0);\n            let d1 = dat1(sb, i0 + 1u);\n            let dd = length(vec2f((u - uc) * L, lat(v - mix(d0, d1, f), d0, d1, step)));\n            let hb = base + (ns + k) * q4;\n            let dh = length(vec2f((u - uc) * L, v - mix(dat1(hb, i0), dat1(hb, i0 + 1u), f)));\n            let bw = select(w * 0.6, w, k == 0u);\n            var bo = shade_bolt(dd, bw, gr);\n            bo.halo = 0.4 * shade_bolt(dh, bw, gr).halo + 0.6 * shade_bolt(dd, bw, gr * 0.3).halo;\n            let kb = select(0.32, 1.0, k == 0u) * fl[k];\n            core += bo.core * kb;\n            halo += bo.halo * kb;\n        }\n        // Electrode hot spots.\n        halo += 0.6 * (gauss(length(c.p - a), gr * 0.8) + gauss(length(c.p - bb), gr * 0.8));\n        core += 0.5 * (gauss(length(c.p - a), w * 2.5) + gauss(length(c.p - bb), w * 2.5));\n        var fb = base + 2u * ns * q4;\n        for (var j = 0u; j < nf; j++) {\n            let h0 = shader_data_at(fb);\n            let h1 = shader_data_at(fb + 1u);\n            let o = h0.xy;\n            let fd = h0.zw;\n            let len = h1.x;\n            let fr = c.p - o;\n            let fu = dot(fr, fd) / len;\n            let fv = dot(fr, vec2f(-fd.y, fd.x));\n            let fuc = clamp(fu, 0.0, h1.y);\n            let ffi = fuc * 15.0;\n            let j0 = min(u32(ffi), 14u);\n            let s0 = dat1(fb + 2u, j0);\n            let s1 = dat1(fb + 2u, j0 + 1u);\n            let fdist = length(vec2f((fu - fuc) * len, lat(fv - mix(s0, s1, ffi - f32(j0)), s0, s1, len / 15.0)));\n            let taper = 1.0 - 0.7 * fuc;\n            let bo = shade_bolt(fdist, w * 0.6 * taper, gr * 0.55);\n            fork_hot += fork_col(i, h1.w) * (bo.core * 1.1 + bo.halo * 0.45) * h1.z * taper;\n            fb += 6u;\n        }\n    } else {\n        let pr = rrect_perim(c.q, c.half, c.r);\n        let s = pr.x;\n        let total = pr.y;\n        let calm = c.variant == 2;\n        let fi = s / total * f32(n);\n        let i0 = u32(floor(fi)) % n;\n        let i1 = (i0 + 1u) % n;\n        let f = fi - floor(fi);\n        let step = total / f32(n);\n        for (var k = 0u; k < ns; k++) {\n            let sb = base + k * q4;\n            let d0 = dat1(sb, i0);\n            let d1 = dat1(sb, i1);\n            let dd = abs(lat(c.d - gap - mix(d0, d1, f), d0, d1, step));\n            let hb = base + (ns + k) * q4;\n            let dh = abs(c.d - gap - mix(dat1(hb, i0), dat1(hb, i1), f));\n            let cb = base + (2u * ns + k) * q4;\n            let crawl = mix(dat1(cb, i0), dat1(cb, i1), f);\n            let bw = select(w * 0.6, w, k == 0u);\n            var bo = shade_bolt(dd, bw, gr);\n            bo.halo = 0.4 * shade_bolt(dh, bw, gr).halo + 0.6 * shade_bolt(dd, bw, gr * 0.3).halo;\n            let kb = select(0.32, 1.0, k == 0u) * fl[k] * crawl;\n            core += bo.core * kb;\n            halo += bo.halo * kb;\n        }\n        if (calm) {\n            // Beads of charge travelling one way around the border.\n            let sp = i.p0.z * 0.35;\n            let bu = fract(s / total - c.t * 0.07 * sp);\n            for (var k = 0; k < 3; k++) {\n                let x = fract(bu - f32(k) / 3.0 + 0.5) - 0.5;\n                let bead = gauss(x * total, 18.0);\n                halo += bead * gauss(c.d - gap, gr * 0.8) * 0.9;\n                core += bead * gauss(c.d - gap, w * 1.5) * 0.6;\n            }\n        }\n        var fb = base + 3u * ns * q4;\n        for (var j = 0u; j < nf; j++) {\n            let h0 = shader_data_at(fb);\n            let h1 = shader_data_at(fb + 1u);\n            let len = h1.x;\n            var dsv = s - h0.x;\n            dsv -= total * round(dsv / total);\n            let fu = (c.d - gap - h0.z) / len;\n            let fuc = clamp(fu, 0.0, h1.y);\n            let ffi = fuc * 15.0;\n            let j0 = min(u32(ffi), 14u);\n            let s0 = dat1(fb + 2u, j0);\n            let s1 = dat1(fb + 2u, j0 + 1u);\n            let fdist = length(vec2f((fu - fuc) * len, lat(dsv - mix(s0, s1, ffi - f32(j0)), s0, s1, len / 15.0)));\n            let taper = 1.0 - 0.7 * fuc;\n            let bo = shade_bolt(fdist, w * 0.6 * taper, gr * 0.55);\n            fork_hot += fork_col(i, h1.w) * (bo.core * 1.1 + bo.halo * 0.45) * h1.z * taper;\n            fb += 6u;\n        }\n    }\n    let occl = select(1.0, i.p2.w, effective_blend_mode(i) == 0u);\n    let rgb = (i.c1.rgb * core * 1.3 + i.c0.rgb * halo * 0.75 + fork_hot) * inten;\n    let a = (core * 0.7 + halo * occl + lum(fork_hot) * 0.5) * inten;\n    return finish(vec4f(rgb, a), in.px);\n}\n";
export const EXTRAS =
  COMMON +
  "// Extras. variant: 0 shimmer/sheen sweep, 1 sparkles, 2 aurora, 3 grain.\n// shimmer: c0 sheen, c1 base (a = 0: none)  p0 (period, band pt, angle rad, intensity)  p1 (use mask, pause, feather, _)\n// sparkle: c0 colour  p0 (count, life s, size pt, intensity)  p1 (margin pt, _, _, _)\n// aurora:  c0 c1 c2 curtains  p0 (scale pt, speed, intensity, feather pt)\n// grain:   p0 (amount, fps (0 = static), feather, _)\n\n// Inner feather: fully inside the shape, so overlays never leak past the node's edge.\nfn cover(c: Ctx, feather: f32) -> f32 { return smoothstep(c.aa * 0.5, -max(feather, c.aa), c.d); }\n\nfn rune_shade(in: VOut) -> vec4f {\n    let i = inst_at();\n    let c = ctx(i, in.px);\n\n    if (c.variant == 0) {\n        var m: f32;\n        if (i.p1.x > 0.5) {\n            m = textureSampleLevel(simulation_state, backdrop_sampler, (c.p - i.aux2.xy) / i.aux2.zw, 0.0).a;\n        } else {\n            m = cover(c, max(i.p1.z, c.aa * 1.5));\n        }\n        if (m <= 0.0) { return vec4f(0.0); }\n        let ta = tan(i.p0.z);\n        let span = c.half.x + c.half.y * abs(ta) + i.p0.y * 2.5;\n        let x = c.q.x + c.q.y * ta;\n        var sheen: f32;\n        if (c.reduced) {\n            // Calm: the whole surface breathes slightly instead of a travelling band.\n            sheen = 0.35 * (0.5 - 0.5 * cos(TAU * c.t / max(i.p0.x, 0.1)));\n        } else {\n            let ph = fract(c.t / max(i.p0.x, 0.1));\n            let travel = clamp(ph / max(1.0 - i.p1.y, 0.05), 0.0, 1.0);\n            let e = travel * travel * (3.0 - 2.0 * travel);\n            let xc = mix(-span, span, e);\n            sheen = gauss(x - xc, i.p0.y) + 0.35 * gauss(x - xc, i.p0.y * 2.6);\n        }\n        let base = i.c1.rgb * i.c1.a;\n        return finish(vec4f(base * m + i.c0.rgb * sheen * i.p0.w * m, i.c1.a * m + sheen * i.p0.w * m * 0.2), in.px);\n    }\n    if (c.variant == 1) {\n        let f0 = u32(i.xf.x);\n        let n = u32(i.xf.y);\n        var body = 0.0;\n        var hot = 0.0;\n        var halo = 0.0;\n        for (var k = 0u; k < n; k++) {\n            let a = shader_data_at(f0 + k * 2u);\n            let b = shader_data_at(f0 + k * 2u + 1u);\n            let S = max(a.z, 0.01);\n            let env = a.w;\n            let rel = c.p - a.xy;\n            let r = length(rel);\n            if (r > S * 1.6) { continue; }\n            let l = vec2f(b.x * rel.x - b.y * rel.y, b.y * rel.x + b.x * rel.y);\n            // Four-point star: |x|^p + |y|^p = 1 with p < 1 gives concave sides and needle tips.\n            // g is homogeneous of degree 1, so (g - 1) * S is roughly a distance in points.\n            let ax = max(abs(l) / S, vec2f(1e-6));\n            let g = pow(pow(ax.x, 0.55) + pow(ax.y, 0.55), 1.0 / 0.55);\n            let w = c.aa * 0.75 / S;\n            let m = 1.0 - smoothstep(1.0 - w, 1.0 + w, g);\n            body += env * m;\n            hot += env * m * (1.0 - g) * (1.0 - g);\n            halo += env * gauss(r, S * 0.32);\n        }\n        let tint = i.c0.rgb;\n        let col = mix(tint, vec3f(1.0), 0.3) * body + vec3f(1.0) * hot * 0.8 + tint * halo * 0.12;\n        return finish(vec4f(col * i.p0.w, min(body * 0.9 + halo * 0.05, 1.0) * i.p0.w), in.px);\n    }\n    if (c.variant == 2) {\n        let m = cover(c, max(i.p0.w, c.aa));\n        if (m <= 0.0) { return vec4f(0.0); }\n        let sc = max(i.p0.x, 1.0);\n        let q = c.p / sc;\n        var t = c.t * i.p0.y;\n        if (c.reduced) { t = 0.0; }\n        let uy = (c.p.y - i.rect.y) / i.rect.w;\n        var col = vec3f(0.0);\n        let cols = array<vec3f, 3>(i.c0.rgb, i.c1.rgb, i.c2.rgb);\n        // Curtain heights and warps across the width are CPU tables (cpu.rs::aurora).\n        let f0 = u32(i.xf.x);\n        let ns = u32(i.xf.y);\n        let fx = clamp((c.p.x - i.rect.x) / i.rect.z, 0.0, 1.0) * f32(ns - 1u);\n        let x0 = min(u32(fx), ns - 2u);\n        let fr = fx - f32(x0);\n        for (var k = 0; k < 3; k++) {\n            let fk = f32(k);\n            let yb = f0 + u32(k) * 2u * (ns >> 2u);\n            let wb = yb + (ns >> 2u);\n            let wv = mix(dat1(wb, x0), dat1(wb, x0 + 1u), fr);\n            let yk = mix(dat1(yb, x0), dat1(yb, x0 + 1u), fr);\n            let band = gauss(uy - yk, 0.13 + 0.05 * fk);\n            let rays = 0.65 + 0.35 * gnoise(vec2f(q.x * 5.0 + wv * 3.0, t * 0.5 + fk), c.seed + 9u);\n            // Curtains have a bright lower hem and fade upward.\n            let hem = smoothstep(yk + 0.16, yk - 0.02, uy) * 0.5 + 0.5;\n            col += cols[k] * band * rays * hem;\n        }\n        let a = select(min(max(col.r, max(col.g, col.b)), 1.0), lum(col) * 0.4, effective_blend_mode(i) == 0u);\n        return finish(vec4f(col * i.p0.z * m, a * i.p0.z * m), in.px);\n    }\n    // Grain.\n    let m = cover(c, max(i.p0.z, c.aa));\n    if (m <= 0.0) { return vec4f(0.0); }\n    var frame = 0u;\n    if (i.p0.y > 0.0 && !c.reduced) { frame = u32(floor(c.t * i.p0.y)); }\n    let ip = vec2u(in.px);\n    let n = u01(ip.x + pcg(ip.y + pcg(frame + c.seed))) + u01(ip.y * 7919u + pcg(ip.x + 17u + frame)) - 1.0;\n    let a = i.p0.x * m;\n    if (n >= 0.0) { return vec4f(vec3f(n * a), n * a); }\n    return vec4f(0.0, 0.0, 0.0, -n * a);\n}\n";
export const DISTORT =
  COMMON +
  "// Distortion of the backdrop (needs `backdrop` = target content right before this layer).\n// variant: 0 heat haze, 1 shockwave, 2 liquid-glass lens, 3 CRT, 4 chromatic split.\n//\n// heat:   p0 (height pt, scale pt, speed, amount pt)  p1 (full rect 0/1, _, _, _)\n// shock:  p0 (reach pt, width pt, amount pt, chroma)  p1 (t0, duration, _, _)  aux: origin\n// lens:   p0 (bevel pt, depth pt, dispersion, magnification)  p1 (presence, frost, shadow, rim)\n//         p2 (light angle rad, tint, union k pt, radius B)  p3 rect B (w = 0: none)  shape.w morph A->B\n//         c0 tint\n// crt:    p0 (bulge, scanline period pt, scanline depth, chroma pt)  p1 (vignette, glow, roll, feather)\n// split:  p0 (offset x pt, offset y pt, glitch, feather)\n\n// Frosted material, after Apple's \"regular\" glass: a saturation boost puts back the colour that\n// blur and scrim take out, and a compressive transfer lifts dark backdrops while light ones\n// barely move (macOS 26 Control Center measures sRGB L' = 0.58 L + 0.134; iOS keeps more of\n// the colour, so this sits a little above that). k = 0..1.\nfn frosted(c: vec3f, k: f32) -> vec3f {\n    let l = lum(c);\n    let sat = max(mix(vec3f(l), c, 1.0 + 0.9 * k), vec3f(0.0));\n    let e = to_srgb(sat);\n    return to_lin(e * (1.0 - 0.32 * k) + vec3f(0.11 * k));\n}\n\nfn lens_sd(c: Ctx, i: Inst, q: vec2f) -> f32 {\n    let da = sd_rrect(q, c.half, c.r);\n    if (i.p3.z <= 0.0) { return da; }\n    let cb = i.p3.xy + i.p3.zw * 0.5 - c.c;\n    let db = sd_rrect(q - cb, i.p3.zw * 0.5, i.p2.w);\n    return mix(smin(da, db, i.p2.z), db, i.shape.w);\n}\n\n// Thin-surface optics (psychopomp math/optics.rs): sideways travel per unit depth through a surface\n// whose tilt rises from vertical at the rim to flat (superellipse bevel, power 3).\nfn bend_at(t: f32) -> f32 {\n    let u = clamp(1.0 - t, 0.0, 0.9999);\n    let pw = 3.0;\n    let slope = pow(u, pw - 1.0) * pow(max(1.0 - pow(u, pw), 1e-6), 1.0 / pw - 1.0);\n    let tilt = atan(min(slope, 1e4));\n    let bent = asin(sin(tilt) / 1.5);\n    return tan(tilt - bent);\n}\n\nfn rune_shade(in: VOut) -> vec4f {\n    let i = inst_at();\n    let c = ctx(i, in.px);\n    let s = c.scale;\n\n    if (c.variant == 0) {\n        let H = i.p0.x;\n        var m: f32;\n        if (i.p1.x > 0.5) {\n            m = smoothstep(c.aa, -c.aa * 8.0, c.d);\n        } else {\n            let above = i.rect.y - c.p.y;\n            let side = smoothstep(c.half.x + 2.0, c.half.x - c.r - 4.0, abs(c.q.x));\n            // Starts just clear of the edge so the shape itself never wobbles, and is strongest a\n            // little up the column where the hot air has risen off the flame tips.\n            m = smoothstep(1.0, 1.0 + H * 0.3, above) * (1.0 - smoothstep(H * 0.45, H, above)) * side;\n        }\n        if (m <= 0.0) { return vec4f(0.0); }\n        var t = c.t;\n        if (c.reduced) { t = 0.0; }\n        let q = c.p / max(i.p0.y, 1.0) + vec2f(0.0, t * i.p0.z);\n        let o = vec2f(fbm3(q, c.seed), fbm3(q * vec2f(1.0, 0.7) + vec2f(7.3, 2.1), c.seed + 5u)) * i.p0.w;\n        let col = bd(c.p + o * m, s);\n        return vec4f(col.rgb, 1.0) * smoothstep(0.0, 0.02, m);\n    }\n    if (c.variant == 1) {\n        let age = c.t - i.p1.x;\n        let dur = max(i.p1.y, 0.05);\n        if (age < 0.0 || age > dur) { return vec4f(0.0); }\n        let u = age / dur;\n        let rel = c.p - i.aux.xy;\n        let r = length(rel);\n        let dir = rel / max(r, 1e-3);\n        let fade = (1.0 - u) * (1.0 - u);\n        if (c.reduced) {\n            // No travel: a soft brightening at the origin that cools.\n            let gl = gauss(r, i.p0.x * 0.25) * 0.12 * fade * smoothstep(0.0, 0.1, u);\n            return vec4f(bd(c.p, s).rgb * gl, 0.0);\n        }\n        let R = i.p0.x * (1.0 - pow(1.0 - u, 2.6));\n        let w = i.p0.y * (1.0 + 1.5 * u);\n        let x = (r - R) / w;\n        let f = x * exp(-x * x) * 2.33;\n        let off = -dir * f * i.p0.z * fade;\n        let ca = i.p0.w * abs(f) * fade;\n        let rr = bd(c.p + off * (1.0 + ca), s).r;\n        let gg = bd(c.p + off, s).g;\n        let bb = bd(c.p + off * (1.0 - ca), s).b;\n        // Highlight only where there is content to catch it (no grey donut over empty space).\n        let lit = max(-f, 0.0) * 0.12 * fade * lum(vec3f(rr, gg, bb));\n        let m = smoothstep(0.0, 0.01, abs(f) * fade);\n        return vec4f(vec3f(rr, gg, bb) + lit, 1.0) * m;\n    }\n    if (c.variant == 2) {\n        let d = lens_sd(c, i, c.q);\n        let presence = i.p1.x;\n        let e = 0.5;\n        let gx = lens_sd(c, i, c.q + vec2f(e, 0.0)) - lens_sd(c, i, c.q - vec2f(e, 0.0));\n        let gy = lens_sd(c, i, c.q + vec2f(0.0, e)) - lens_sd(c, i, c.q - vec2f(0.0, e));\n        let nrm = vec2f(gx, gy) / max(length(vec2f(gx, gy)), 1e-5);\n        let coverage = clamp(0.5 - d * s, 0.0, 1.0);\n        // Drop shadow + contact (outside), scaled by presence: glass materialises by lensing.\n        let sd = lens_sd(c, i, c.q - vec2f(0.0, 5.0 * presence));\n        let fall = exp(-pow(max(sd + 2.0, 0.0), 2.0) / (2.0 * 9.0 * 9.0));\n        let contact = exp(-pow(max(d, 0.0), 2.0) / 6.0);\n        let dark = min(i.p1.z * presence * (0.55 * fall + 0.45 * contact), 1.0) * (1.0 - coverage);\n        if (coverage <= 0.0) {\n            return vec4f(0.0, 0.0, 0.0, dark);\n        }\n        let depth = -d;\n        let bevel = max(i.p0.x, 0.5);\n        let tt = clamp(depth / bevel, 0.0, 1.0);\n        let bend = i.p0.y * bend_at(tt) * presence;\n        let mag = mix(1.0, i.p0.w, presence);\n        let ctr = c.c;\n        let inward = -nrm;\n        let dsp = i.p0.z;\n        let local = c.p - ctr;\n        let srcg = ctr + (local + inward * bend) / mag;\n        let srcr = ctr + (local + inward * bend * (1.0 - dsp)) / mag;\n        let srcb = ctr + (local + inward * bend * (1.0 + dsp)) / mag;\n        var col = vec3f(bd(srcr, s).r, bd(srcg, s).g, bd(srcb, s).b);\n        let frost = i.p1.y;\n        if (frost > 0.0 && i.xf.x > 0.5) {\n            // Frosted: the dual-filter pyramid, refracted like the clear image (so the rim still\n            // bends and splits), then the material transfer and a static grain against banding.\n            let blr = vec3f(bdb(srcr, s).r, bdb(srcg, s).g, bdb(srcb, s).b);\n            col = mix(col, blr, i.xf.y);\n            let k = presence * smoothstep(0.0, 0.6, frost);\n            col = frosted(col, k);\n            let ip = vec2u(in.px);\n            let n = u01(ip.x + pcg(ip.y + 7u)) - u01(ip.x * 7919u + pcg(ip.y + 31u));\n            col = to_lin(max(to_srgb(col) + vec3f(n * 1.6 / 255.0 * k), vec3f(0.0)));\n        } else {\n            // Rim softening where the page is squeezed into a thin band (+ a small fallback frost\n            // when no pyramid was built).\n            let rim = bend / max(1.118 * i.p0.y, 1e-3);\n            let soften = min(pow(rim, 1.5) * 0.55, 1.0);\n            if (soften > 1e-3 || frost > 0.0) {\n                let rad = mix(1.2, 10.0, frost);\n                let j = ign(in.px) * TAU;\n                var acc = vec3f(0.0);\n                for (var k = 0; k < 8; k++) {\n                    let a = j + f32(k) * 2.39996;\n                    let rr = rad * sqrt((f32(k) + 0.5) / 8.0);\n                    acc += bd(srcg + vec2f(cos(a), sin(a)) * rr, s).rgb;\n                }\n                acc /= 8.0;\n                col = mix(col, acc, clamp(max(soften, frost), 0.0, 1.0));\n            }\n        }\n        col = mix(col, col * i.c0.rgb, i.p2.y * presence);\n        // Light: sky sheen, crisp specular where the rim faces the light, a fainter counter-line, hairline.\n        let la = i.p2.x;\n        let L = vec2f(cos(la), sin(la));\n        let facing = max(dot(nrm, L), 0.0);\n        let away = max(-dot(nrm, L), 0.0);\n        let sky = clamp(0.5 - 0.5 * c.q.y / c.half.y, 0.0, 1.0);\n        let rimk = i.p1.w;\n        let fres = pow(1.0 - tt, 3.0) * 0.05 * (0.25 + 0.75 * sky);\n        let line = gauss(depth - 0.75, 0.55);\n        let glow = gauss(depth - 1.4, 2.4);\n        let spec = line * (0.9 * pow(facing, 2.5) + 0.35 * pow(away, 3.0)) + glow * 0.1 * pow(facing, 4.0);\n        let inner = gauss(tt - 0.32, 0.18) * away * away * 0.06;\n        let edge = gauss(depth - 0.3, 0.45) * 0.12;\n        let light = (0.004 + fres + spec + inner + edge) * presence * rimk;\n        col = col * (1.0 - 0.04 * presence) + vec3f(light);\n        // Coverage blends glass over the untouched backdrop + shadow.\n        let base = bd(c.p, s).rgb * (1.0 - dark);\n        return vec4f(mix(base, col, coverage), 1.0);\n    }\n    if (c.variant == 3) {\n        let feather = max(i.p1.w, c.aa);\n        let m = smoothstep(feather * 0.5, -feather * 0.5, c.d);\n        if (m <= 0.0) { return vec4f(0.0); }\n        let uv = c.q / c.half;\n        let k = i.p0.x;\n        let bu = uv * (1.0 + k * dot(uv, uv)) / (1.0 + k);\n        let inside = smoothstep(1.0, 0.985, max(abs(bu.x), abs(bu.y)));\n        let src = c.c + bu * c.half;\n        let ca = i.p0.w;\n        var col = vec3f(bd(src + vec2f(ca, 0.0), s).r, bd(src, s).g, bd(src - vec2f(ca, 0.0), s).b);\n        // Glow: cheap 4-tap bloom of the simulation_state.\n        let gw = 3.0;\n        let gl = (bd(src + vec2f(gw, 0.0), s).rgb + bd(src - vec2f(gw, 0.0), s).rgb + bd(src + vec2f(0.0, gw), s).rgb + bd(src - vec2f(0.0, gw), s).rgb) * 0.25;\n        col += gl * i.p1.y;\n        let per = max(i.p0.y, 3.0 * c.aa);\n        let sl = 0.5 + 0.5 * cos(TAU * (c.p.y - i.rect.y) / per);\n        col *= 1.0 - i.p0.z * (1.0 - sl);\n        // Aperture grille, very subtle.\n        let col3 = u32(floor(in.px.x)) % 3u;\n        let grille = select(select(vec3f(0.94, 0.94, 1.0), vec3f(0.94, 1.0, 0.94), col3 == 1u), vec3f(1.0, 0.94, 0.94), col3 == 0u);\n        col *= grille;\n        var roll = 0.0;\n        if (!c.reduced) { roll = gauss(fract((c.p.y - i.rect.y) / i.rect.w - c.t * 0.12) - 0.5, 0.06) * i.p1.z; }\n        col += vec3f(roll) * 0.06;\n        col *= 1.0 - i.p1.x * pow(dot(uv, uv) * 0.5, 1.5);\n        col *= inside;\n        return vec4f(col, 1.0) * m;\n    }\n    // Chromatic split with optional glitch slices.\n    let feather = max(i.p0.w, c.aa);\n    let m = smoothstep(feather * 0.5, -feather * 0.5, c.d);\n    if (m <= 0.0) { return vec4f(0.0); }\n    var o = i.p0.xy;\n    var gx = 0.0;\n    if (i.p0.z > 0.0 && !c.reduced) {\n        let slice = floor((c.p.y - i.rect.y) / 6.0);\n        let fr = floor(c.t * 12.0);\n        let hsl = hu(c.seed + bitcast<u32>(i32(slice)), bitcast<u32>(i32(fr)));\n        if (u01(hsl) < 0.12 * i.p0.z) { gx = (u01(hsl + 1u) - 0.5) * 16.0 * i.p0.z; }\n    }\n    let p = c.p + vec2f(gx, 0.0);\n    let col = vec3f(bd(p + o, s).r, bd(p, s).g, bd(p - o, s).b);\n    return vec4f(col, 1.0) * m;\n}\n";
export const FILL =
  COMMON +
  "// Fills: styles that paint the node's shape, or a band inside its edge (aux.x = border pt, 0 = whole\n// shape). aux.y = intensity. Colour lists live in the CPU table: for stop k, shader_data_at(xf.x + 2k) is\n// linear rgb (w: mesh point x), shader_data_at(xf.x + 2k + 1) is OKLab (w: mesh point y); xf.y stops.\n// variant:\n// 0 liquid metal  c0 tint  c1 light  p0 (flow, scale pt, speed, bevel pt)  p1 (dome, angle, iridescence, contrast)\n//                 p2 (anchor: 0 window, 1 shape, _, _, _)\n// 1 mesh          p0 (drift, speed, sharpness, warp)  (points are animated on the CPU)\n// 2 dither        p0 (pattern, input, pixel pt, ramp angle)  p1 (noise scale pt, speed, bias, contrast)\n//                 xf.zw blue-noise tile (offset, side)\n// 3 grain grad.   p0 (kind, angle, centre x, centre y)  p1 (amount, size pt, mono, fps)\n// 4 fluted glass  c0 tint  p0 (rib pt, angle, refraction pt, frost)  p1 (dispersion, highlight, tint amount, _)\n//                 xf.xy frost pyramid (set by FxRenderer::blur_backdrop)\n// 5 metaballs     c0 base  p0 (count, size, speed, gloss)  xf.z balls: (x pt, y pt, r pt, stop)\n// 6 swirl         p0 (scale pt, speed, twist, warp)\n// 7 voronoi       c0 seam  p0 (cell pt, speed, seam pt, depth)\n// 8 waves         p0 (amplitude, frequency, speed, angle)  p1 (softness, _, _, _)\n// 9 halftone      c0 ink  c1 base  p0 (_, input, pitch pt, ramp angle)  p1 as dither  p2 (screen angle, _, _, _)\n// 10 plastic      c0 colour  p0 (roughness, dome, bevel pt, light angle)\n\n// Shape coverage: the whole shape, or (border > 0) a band of that width inside the edge.\nfn fill_mask(c: Ctx, border: f32) -> f32 {\n    let inside = clamp(0.5 - c.d * c.scale, 0.0, 1.0);\n    if (border <= 0.0) { return inside; }\n    return inside * clamp(0.5 + (c.d + border) * c.scale, 0.0, 1.0);\n}\n\nfn rot2(v: vec2f, a: f32) -> vec2f {\n    let cs = cos(a);\n    let sn = sin(a);\n    return vec2f(cs * v.x - sn * v.y, sn * v.x + cs * v.y);\n}\n\n// ---------- colour lists ----------\nfn stop_lin(f0: u32, k: u32) -> vec3f { return shader_data_at(f0 + 2u * k).rgb; }\nfn stop_lab(f0: u32, k: u32) -> vec3f { return shader_data_at(f0 + 2u * k + 1u).rgb; }\nfn stop_pt(f0: u32, k: u32) -> vec2f { return vec2f(shader_data_at(f0 + 2u * k).w, shader_data_at(f0 + 2u * k + 1u).w); }\n\nfn oklab_to_lin(c: vec3f) -> vec3f {\n    let l = c.x + 0.39633778 * c.y + 0.21580376 * c.z;\n    let m = c.x - 0.10556135 * c.y - 0.06385417 * c.z;\n    let s = c.x - 0.08948418 * c.y - 1.29148555 * c.z;\n    let l3 = l * l * l;\n    let m3 = m * m * m;\n    let s3 = s * s * s;\n    return max(vec3f(\n        4.07674166 * l3 - 3.30771159 * m3 + 0.23096993 * s3,\n        -1.26843800 * l3 + 2.60975740 * m3 - 0.34131940 * s3,\n        -0.00419609 * l3 - 0.70341861 * m3 + 1.70761470 * s3,\n    ), vec3f(0.0));\n}\n\n// The colour list as an even ramp over x in 0..1, blended in OKLab.\nfn palette_ramp(f0: u32, n: u32, x: f32) -> vec3f {\n    if (n <= 1u) { return stop_lin(f0, 0u); }\n    let fx = clamp(x, 0.0, 1.0) * f32(n - 1u);\n    let k = min(u32(fx), n - 2u);\n    return oklab_to_lin(mix(stop_lab(f0, k), stop_lab(f0, k + 1u), fx - f32(k)));\n}\n\n// The colour list as a closed loop over x in 0..1: the last colour blends back into the first.\nfn ramp_loop(f0: u32, n: u32, x: f32) -> vec3f {\n    if (n <= 1u) { return stop_lin(f0, 0u); }\n    let fx = fract(x) * f32(n);\n    let k = min(u32(fx), n - 1u);\n    return oklab_to_lin(mix(stop_lab(f0, k), stop_lab(f0, (k + 1u) % n), fx - f32(k)));\n}\n\n// Premultiplied output with the fill's coverage and intensity.\nfn paint(col: vec3f, m: f32, i: Inst, px: vec2f) -> vec4f {\n    let a = m * clamp(i.aux.y, 0.0, 1.0);\n    return finish(vec4f(col * a, a), px);\n}\n\n// ---------- tone inputs (dither, halftone) ----------\n// Perceptual tone 0..1 at `p` for input `kind`: 0 linear ramp, 1 radial, 2 noise, 3 backdrop, 4 image.\nfn tone_at(i: Inst, c: Ctx, p: vec2f, kind: i32, angle: f32) -> f32 {\n    var v: f32;\n    let q = p - c.c;\n    if (kind == 0) {\n        let dir = vec2f(cos(angle), sin(angle));\n        let ext = abs(c.half.x * dir.x) + abs(c.half.y * dir.y);\n        v = dot(q, dir) / max(ext, 1e-3) * 0.5 + 0.5;\n    } else if (kind == 1) {\n        v = 1.0 - clamp(length(q / max(c.half, vec2f(1e-3))) / 1.3, 0.0, 1.0);\n    } else if (kind == 2) {\n        let t = c.t * i.p1.y;\n        v = 0.5 + 0.62 * fbm3(p / max(i.p1.x, 1.0) + vec2f(t * 0.31, t * 0.17), c.seed);\n    } else if (kind == 3) {\n        v = to_srgb(vec3f(lum(bd(p, c.scale).rgb))).x;\n    } else {\n        let s = textureSampleLevel(simulation_state, backdrop_sampler, (p - i.aux2.xy) / max(i.aux2.zw, vec2f(1e-3)), 0.0);\n        v = to_srgb(vec3f(lum(s.rgb))).x;\n    }\n    return clamp((v - 0.5) * i.p1.w + 0.5 + i.p1.z * 0.5, 0.0, 1.0);\n}\n\n// Ordered-dither threshold of an n\u00d7n Bayer matrix (n = 2^bits), from the bit-interleave recurrence.\nfn bayer(cell: vec2u, bits: u32) -> f32 {\n    var v = 0u;\n    for (var b = 0u; b < bits; b++) {\n        let x = (cell.x >> b) & 1u;\n        let y = (cell.y >> b) & 1u;\n        let sh = 2u * (bits - 1u - b);\n        v |= (((x ^ y) << 1u) | y) << sh;\n    }\n    return (f32(v) + 0.5) / f32(1u << (2u * bits));\n}\n\n// ---------- lit slabs (liquid metal, plastic) ----------\n// Slope of a slab's surface normal as (x, y) plus how far onto the rim it is (0..1). With a border\n// the band is a round tube; otherwise the edge rolls off in a quarter round over `bevel` pt and\n// the face is domed (negative `dome` dishes it).\nfn slab_tilt(c: Ctx, border: f32, bevel: f32, dome: f32) -> vec3f {\n    let depth = -c.d;\n    let gv = sd_grad(c);\n    var tilt = vec2f(0.0);\n    var rim = 0.0;\n    if (border > 0.0) {\n        let x = clamp((depth - border * 0.5) / max(border * 0.5, 1e-3), -0.97, 0.97);\n        tilt = -gv * x / sqrt(1.0 - x * x);\n        rim = abs(x);\n    } else {\n        let bev = max(bevel, 0.5);\n        let x = clamp(1.0 - depth / bev, 0.0, 0.92);\n        tilt = gv * x / sqrt(1.0 - x * x);\n        rim = x;\n    }\n    let qn = c.q / max(c.half, vec2f(1.0));\n    tilt += vec2f(qn.x * 0.55, qn.y) * dome * select(0.8, 0.25, border > 0.0);\n    return vec3f(tilt, rim);\n}\n\n// ---------- liquid metal ----------\n// Height of the flowing surface (in units of `scale`), domain-warped so ripples curl and pool.\nfn flow_h(u: vec2f, w: vec2f, t: f32, seed: u32) -> f32 {\n    let p = u + w;\n    return gnoise(p + vec2f(0.0, t * 0.11), seed + 3u) + 0.5 * gnoise(ROT * p * 2.03 - vec2f(t * 0.07, 0.0), seed + 17u);\n}\n\n// A photo studio seen from a polished object, by reflected direction r (screen y points down, +z\n// toward the viewer): a bright sky that is lightest just above a hard horizon, an overhead soft\n// box, a tall strip light on the right and a dim one on the left, over a dark floor that lightens\n// away from the horizon. White lights; the caller tints them.\nfn studio(r: vec3f, contrast: f32) -> vec3f {\n    let up = -r.y;\n    let e = up + 0.1; // elevation above the horizon (which sits a little below eye level)\n    let w = 0.014;\n    let sky = 0.2 + 0.6 * exp(-max(e, 0.0) * 3.2) + 0.45 * exp(-max(e, 0.0) * 24.0);\n    let key = smoothstep(0.80, 0.95, dot(r, normalize(vec3f(-0.3, -0.82, 0.5)))) * 2.4;\n    let strip = gauss(r.x - 0.6, 0.075) * smoothstep(-0.05, 0.2, e) * (1.0 - smoothstep(0.55, 0.9, up)) * 1.7;\n    let fill_l = gauss(r.x + 0.72, 0.045) * smoothstep(0.0, 0.25, e) * (1.0 - smoothstep(0.4, 0.8, up)) * 0.55;\n    let lights = (key + strip + fill_l) * contrast;\n    // The floor: near black under the horizon, lifting toward the camera, with a soft pool of\n    // bounced light off to the left.\n    let fl = smoothstep(0.05, 1.0, -e);\n    let pool = 0.16 * gauss(r.x + 0.25, 0.35) * smoothstep(0.25, 0.9, -e);\n    let ground = (0.014 + 0.3 * fl * fl + pool + 0.05 * gauss(e + 0.06, 0.04)) / (contrast * contrast);\n    let h = smoothstep(-w, w, e);\n    let skyc = (sky * mix(1.0, 0.82, clamp(contrast - 1.0, 0.0, 1.0)) + lights) * vec3f(0.97, 0.99, 1.03);\n    let floorc = ground * vec3f(1.04, 1.0, 0.95);\n    return mix(floorc, skyc, h);\n}\n\n// Gentle shoulder so lights roll off instead of clipping (per channel: hot gold goes pale).\nfn shoulder(c: vec3f) -> vec3f {\n    let k = 0.78;\n    return select(c, k + (1.0 - k) * (1.0 - exp(-(c - k) / (1.0 - k))), c > vec3f(k));\n}\n\nfn liquid_metal(i: Inst, c: Ctx, m: f32, px: vec2f) -> vec4f {\n    let flow = i.p0.x;\n    let sc = max(i.p0.y, 1.0);\n    let t = c.t * i.p0.z;\n    // Tilt of the surface normal (where it leans, as a slope): rim or tube + dome + liquid ripples.\n    let slab = slab_tilt(c, i.aux.x, i.p0.w, i.p1.x);\n    var tilt = slab.xy;\n    let rim = slab.z;\n    var hgt = 0.0;\n    var bend = 0.0;\n    if (flow > 0.0) {\n        // Pinned to the window, or to the shape's centre so equal shapes ripple alike.\n        let u = select(c.p + frame.bounds.xy / frame.scale, c.q, i.p2.x > 0.5) / sc;\n        let wv = vec2f(gnoise(u * 0.6 + vec2f(t * 0.05, 1.7), c.seed + 7u), gnoise(u * 0.6 + vec2f(4.3, -t * 0.06), c.seed + 11u)) * 0.9;\n        let e = 0.04;\n        hgt = flow_h(u, wv, t, c.seed);\n        let hx = flow_h(u + vec2f(e, 0.0), wv, t, c.seed) - hgt;\n        let hy = flow_h(u + vec2f(0.0, e), wv, t, c.seed) - hgt;\n        let grad = vec2f(hx, hy) / e;\n        // Ripples calm toward the rim so the silhouette stays crisp.\n        let k = flow * 0.42 * (1.0 - 0.6 * rim * rim);\n        tilt -= grad * k;\n        bend = length(grad) * k;\n    }\n    let n = normalize(vec3f(tilt, 1.0));\n    var r = vec3f(2.0 * n.z * n.xy, 2.0 * n.z * n.z - 1.0);\n    r = vec3f(rot2(r.xy, i.p1.y), r.z);\n    let contrast = max(i.p1.w, 0.1);\n    let env = studio(normalize(r), contrast) * i.c1.rgb;\n    // Conductor Fresnel (Schlick): the tint at normal incidence, rising to white at grazing angles.\n    let f0 = i.c0.rgb;\n    let cz = clamp(1.0 - n.z, 0.0, 1.0);\n    let cz2 = cz * cz;\n    var f = f0 + (vec3f(1.0) - f0) * (cz2 * cz2 * cz);\n    let ir = i.p1.z;\n    if (ir > 0.0) {\n        // Thin-film colour where the surface bends hardest.\n        let ph = 1.6 * (1.0 - n.z) + 0.35 * hgt;\n        let film = 0.5 + 0.5 * cos(TAU * (vec3f(ph) + vec3f(0.0, 0.33, 0.67)));\n        let k = ir * clamp(smoothstep(0.04, 0.45, 1.0 - n.z) + bend * 0.8, 0.0, 1.0);\n        f *= mix(vec3f(1.0), 0.55 + 0.9 * film, k);\n    }\n    let col = shoulder(f * env);\n    return paint(col, m, i, px);\n}\n\n// ---------- plastic ----------\n// A dielectric under one soft light from `angle` (50\u00b0 up), seen head on. The diffuse base keeps the\n// colour on a flat face, darkens away from the light and lightens toward white facing it. The\n// highlight is a GGX lobe widened by the light's size (so a polished face shows a soft spot, not a\n// pinpoint) and the grazing-angle reflection is a faint sky. Both fill the headroom left above the\n// base, so the colour never exceeds coverage and the fill blends alike in either blend mode.\nfn plastic(i: Inst, c: Ctx, m: f32, px: vec2f) -> vec4f {\n    let slab = slab_tilt(c, i.aux.x, i.p0.z, i.p0.y);\n    let n = normalize(vec3f(slab.xy, 1.0));\n    let l = vec3f(rot2(vec2f(0.0, -1.0), i.p0.w) * 0.6428, 0.766);\n    let nl = dot(n, l);\n    let base = clamp(i.c0.rgb, vec3f(0.0), vec3f(1.0));\n    // 0.4 ambient + 0.6 direct on a flat face (n.l = 0.766).\n    let shade = 0.4 + 0.7833 * max(nl, 0.0);\n    var col = mix(base * min(shade, 1.0), vec3f(1.0), clamp((shade - 1.0) * 0.6, 0.0, 1.0));\n    let rough = clamp(i.p0.x, 0.02, 1.0);\n    let a = min(rough * rough + 0.1, 1.0);\n    let a2 = a * a;\n    let h = normalize(l + vec3f(0.0, 0.0, 1.0));\n    let nh = max(dot(n, h), 0.0);\n    let dd = nh * nh * (a2 - 1.0) + 1.0;\n    let ndf = a2 / (PI * dd * dd);\n    let fh = 1.0 - h.z;\n    let spec = ndf * (0.04 + 0.96 * fh * fh * fh * fh * fh) * max(nl, 0.0) * 2.5;\n    let fz = 1.0 - clamp(n.z, 0.0, 1.0);\n    let sky = 0.55 + 0.45 * smoothstep(-0.5, 0.5, -n.y);\n    let edge = 0.96 * fz * fz * fz * fz * fz * sky * (1.0 - 0.5 * rough);\n    col += (vec3f(1.0) - col) * knee(spec + edge);\n    return paint(col, m, i, px);\n}\n\n// ---------- fluted glass ----------\nfn fluted(i: Inst, c: Ctx, m: f32, px: vec2f) -> vec4f {\n    let s = c.scale;\n    let rib = max(i.p0.x, 1.0);\n    let across = vec2f(cos(i.p0.y), sin(i.p0.y));\n    let u = dot(c.p - c.c, across) / rib;\n    let local = fract(u) - 0.5;\n    let x = local * 2.0; // -1..1 across one rib\n    // A convex rib acts as a cylindrical lens: the strip under it comes back squeezed and flipped.\n    let o = -x * (1.0 + 0.35 * x * x) * i.p0.z;\n    let dsp = i.p1.x * 0.3 * abs(x);\n    let srcg = c.p + across * o;\n    let srcr = c.p + across * o * (1.0 + dsp);\n    let srcb = c.p + across * o * (1.0 - dsp);\n    var col = vec3f(bd(srcr, s).r, bd(srcg, s).g, bd(srcb, s).b);\n    let frost = i.p0.w;\n    if (frost > 0.0) {\n        if (i.xf.x > 0.5) {\n            let blr = vec3f(bdb(srcr, s).r, bdb(srcg, s).g, bdb(srcb, s).b);\n            col = mix(col, blr, i.xf.y);\n        } else {\n            // No pyramid this frame: a small blur along the ribs.\n            let along = vec2f(-across.y, across.x);\n            let j = ign(px) - 0.5;\n            var acc = vec3f(0.0);\n            for (var k = 0; k < 4; k++) {\n                acc += bd(srcg + along * (f32(k) - 1.5 + j) * 3.0 * frost, s).rgb;\n            }\n            col = mix(col, acc * 0.25, frost);\n        }\n        let k = smoothstep(0.0, 0.6, frost);\n        let l = lum(col);\n        let sat = max(mix(vec3f(l), col, 1.0 + 0.5 * k), vec3f(0.0));\n        col = to_lin(to_srgb(sat) * (1.0 - 0.2 * k) + vec3f(0.07 * k));\n    }\n    col = mix(col, col * i.c0.rgb, i.p1.z);\n    // Light: a sheen down each rib's lit side, a shaded groove between ribs with a bright lip.\n    let hl = i.p1.y;\n    let aa = c.aa / rib;\n    let groove = 1.0 - smoothstep(0.0, max(0.06, aa * 2.0), 0.5 - abs(local));\n    // The sheen scales with what is behind (glass reflects little over black) plus a faint floor.\n    let sheen = gauss(local + 0.22, 0.13) * 0.1 + gauss(local + 0.34, 0.03) * 0.1;\n    let lip = gauss(local - 0.44, max(0.025, aa)) * 0.06;\n    let lift = 0.35 + 0.65 * sqrt(clamp(lum(col), 0.0, 1.0));\n    col = col * (1.0 - 0.28 * hl * groove) + vec3f((sheen + lip) * hl * lift);\n    let a = m * clamp(i.aux.y, 0.0, 1.0);\n    return vec4f(col * a, a);\n}\n\n// ---------- the rest ----------\nfn mesh_gradient(i: Inst, c: Ctx, m: f32, px: vec2f) -> vec4f {\n    let f0 = u32(i.xf.x);\n    let n = u32(i.xf.y);\n    var uv = (c.p - i.rect.xy) / max(i.rect.zw, vec2f(1.0));\n    let t = c.t * i.p0.y;\n    let warp = i.p0.w;\n    if (warp > 0.0) {\n        uv += warp * 0.09 * vec2f(gnoise(uv * 2.1 + vec2f(t * 0.11, 0.0), c.seed + 5u), gnoise(uv * 2.1 + vec2f(3.7, -t * 0.09), c.seed + 9u));\n    }\n    let aspect = i.rect.zw / max(max(i.rect.z, i.rect.w), 1.0);\n    let sharp = clamp(i.p0.z, 0.1, 8.0);\n    var lab = vec3f(0.0);\n    var wsum = 0.0;\n    for (var k = 0u; k < n; k++) {\n        let d = (uv - stop_pt(f0, k)) * aspect;\n        // Shepard weights: each colour owns its point, blends fall off smoothly.\n        let w = pow(dot(d, d) + 0.004, -sharp);\n        lab += stop_lab(f0, k) * w;\n        wsum += w;\n    }\n    return paint(oklab_to_lin(lab / max(wsum, 1e-6)), m, i, px);\n}\n\nfn dither(i: Inst, c: Ctx, m: f32) -> vec4f {\n    let f0 = u32(i.xf.x);\n    let n = max(u32(i.xf.y), 1u);\n    let pix = max(i.p0.z, 0.25);\n    let rel = c.p - i.rect.xy;\n    let cell = floor(rel / pix);\n    let ci = bitcast<vec2u>(vec2i(cell));\n    let tone = tone_at(i, c, i.rect.xy + (cell + 0.5) * pix, i32(i.p0.y + 0.5), i.p0.w);\n    let pat = clamp(i32(i.p0.x + 0.5), 1, 5);\n    var th: f32;\n    if (pat <= 3) {\n        th = bayer(ci, u32(pat));\n    } else if (pat == 4) {\n        let side = max(u32(i.xf.w), 1u);\n        th = dat1(u32(i.xf.z), (ci.y % side) * side + ci.x % side);\n    } else {\n        th = u01(ci.x * 7919u + pcg(ci.y + c.seed));\n    }\n    let lv = f32(max(n, 2u) - 1u);\n    let v = tone * lv;\n    let k = min(u32(floor(v) + select(0.0, 1.0, fract(v) > th)), n - 1u);\n    let a = m * clamp(i.aux.y, 0.0, 1.0);\n    return vec4f(stop_lin(f0, k) * a, a);\n}\n\nfn grain_gradient(i: Inst, c: Ctx, m: f32, px: vec2f) -> vec4f {\n    let f0 = u32(i.xf.x);\n    let n = u32(i.xf.y);\n    let kind = i32(i.p0.x + 0.5);\n    let ang = i.p0.y;\n    let ctr = i.rect.xy + i.p0.zw * i.rect.zw;\n    var x: f32;\n    if (kind == 0) {\n        let dir = vec2f(cos(ang), sin(ang));\n        let ext = abs(c.half.x * dir.x) + abs(c.half.y * dir.y);\n        x = dot(c.q, dir) / max(ext, 1e-3) * 0.5 + 0.5;\n    } else if (kind == 1) {\n        x = length(c.p - ctr) / max(length(c.half), 1e-3);\n    } else {\n        let d = c.p - ctr;\n        let th = select(0.0, atan2(d.y, d.x), any(d != vec2f(0.0)));\n        x = fract((th - ang) / TAU);\n    }\n    let amount = i.p1.x;\n    let size = max(i.p1.y, 0.25);\n    var frame = 0u;\n    if (i.p1.w > 0.0) { frame = u32(floor(c.t * i.p1.w)); }\n    let gc = bitcast<vec2u>(vec2i(floor((c.p - i.rect.xy) / size)));\n    let h = pcg(gc.x + pcg(gc.y + pcg(frame + c.seed * 977u)));\n    // Triangular noise scatters the ramp position: colours stipple into each other.\n    let nx = u01(h) + u01(h + 1u) - 1.0;\n    var col = palette_ramp(f0, n, x + nx * amount * 0.2);\n    if (kind == 2) {\n        col = ramp_loop(f0, n, x + nx * amount * 0.2);\n    }\n    let nb = u01(h + 2u) + u01(h + 3u) - 1.0;\n    if (i.p1.z > 0.5) {\n        col *= 1.0 + nb * amount * 0.18;\n    } else {\n        let nc = vec3f(nb, u01(h + 4u) + u01(h + 5u) - 1.0, u01(h + 6u) + u01(h + 7u) - 1.0);\n        col *= vec3f(1.0) + nc * amount * 0.18;\n    }\n    return paint(col, m, i, px);\n}\n\nfn metaballs(i: Inst, c: Ctx, m: f32, px: vec2f) -> vec4f {\n    let f0 = u32(i.xf.x);\n    let b0 = u32(i.xf.z);\n    let nb = u32(i.xf.w);\n    var field = 0.0;\n    var grad = vec2f(0.0);\n    var lab = vec3f(0.0);\n    var rsum = 0.0;\n    for (var k = 0u; k < nb; k++) {\n        let b = shader_data_at(b0 + k);\n        let d = c.p - b.xy;\n        let r2 = b.z * b.z;\n        let dd = dot(d, d) + 1e-3;\n        let f = r2 / dd;\n        field += f;\n        grad += -2.0 * f / dd * d;\n        lab += stop_lab(f0, u32(b.w)) * f;\n        rsum += b.z * f;\n    }\n    let base = i.c0.rgb;\n    let col = select(base, oklab_to_lin(lab / max(field, 1e-6)), field > 1e-5);\n    let ravg = rsum / max(field, 1e-6);\n    // Distance to the iso-surface field = 1, roughly (1 - field) * r / 2 near the edge.\n    let cov = select(0.0, clamp(0.5 + (field - 1.0) * ravg * 0.5 * c.scale, 0.0, 1.0), field > 1e-3);\n    // Glossy body: the field's slope tilts the normal near the rim, flat in the middle.\n    let steep = 1.0 - smoothstep(1.0, 2.6, field);\n    let nxy = -grad / sqrt(dot(grad, grad) + 1e-6) * steep * 0.9;\n    let nrm = normalize(vec3f(nxy, 1.0));\n    let l = normalize(vec3f(-0.45, -0.6, 0.66));\n    let diff = max(dot(nrm, l), 0.0);\n    let spec = pow(max(dot(reflect(-l, nrm), vec3f(0.0, 0.0, 1.0)), 1e-4), 28.0);\n    let body = col * (0.6 + 0.5 * diff) + vec3f(spec * i.p0.w * 0.8);\n    // A soft glow of each blob's colour into the base.\n    let halo = col * smoothstep(0.25, 1.0, field) * 0.18;\n    return paint(mix(base + halo, body, cov), m, i, px);\n}\n\nfn swirl(i: Inst, c: Ctx, m: f32, px: vec2f) -> vec4f {\n    let f0 = u32(i.xf.x);\n    let n = u32(i.xf.y);\n    let sc = max(i.p0.x, 1.0);\n    let t = c.t * i.p0.y;\n    let rr = length(c.q) / max(min(c.half.x, c.half.y), 1.0);\n    let q = rot2(c.q, i.p0.z * TAU * exp(-rr * rr * 0.8)) / sc;\n    let w1 = vec2f(fbm3(q + vec2f(t * 0.1, 0.0), c.seed), fbm3(q + vec2f(5.2, 1.3 - t * 0.08), c.seed + 3u));\n    let v = fbm3(q + w1 * i.p0.w * 1.5 + vec2f(0.0, t * 0.05), c.seed + 7u);\n    return paint(palette_ramp(f0, n, 0.5 + 0.75 * v), m, i, px);\n}\n\nfn voronoi(i: Inst, c: Ctx, m: f32, px: vec2f) -> vec4f {\n    let f0 = u32(i.xf.x);\n    let n = u32(i.xf.y);\n    let sc = max(i.p0.x, 2.0);\n    let t = c.t * i.p0.y;\n    let t0 = fract(t * (1.0 / TAU)) * TAU;\n    let t1 = fract(t * (0.8 / TAU)) * TAU;\n    let p = (c.p - i.rect.xy) / sc;\n    let ip = floor(p);\n    // Each cell's seed point orbits its own spot.\n    var best = 8.0;\n    var bc = vec2i(0);\n    var bo = vec2f(0.0);\n    for (var y = -1; y <= 1; y++) {\n        for (var x = -1; x <= 1; x++) {\n            let cc = vec2i(ip) + vec2i(x, y);\n            let h = hcell(cc, c.seed);\n            let h2 = hcell(cc, c.seed + 1u);\n            let o = vec2f(0.5) + 0.38 * vec2f(sin(t0 + TAU * h), cos(t1 + TAU * h2));\n            let d = vec2f(cc) + o - p;\n            let dd = dot(d, d);\n            if (dd < best) { best = dd; bc = cc; bo = d; }\n        }\n    }\n    // Distance to the nearest seam: to the bisector with each neighbour. Seed points stay within\n    // 0.12..0.88 of their cell, so the eight cells round the winner are enough in practice.\n    var edge = 8.0;\n    for (var y = -1; y <= 1; y++) {\n        for (var x = -1; x <= 1; x++) {\n            let cc = bc + vec2i(x, y);\n            if (x == 0 && y == 0) { continue; }\n            let h = hcell(cc, c.seed);\n            let h2 = hcell(cc, c.seed + 1u);\n            let o = vec2f(0.5) + 0.38 * vec2f(sin(t0 + TAU * h), cos(t1 + TAU * h2));\n            let d = vec2f(cc) + o - p;\n            let dv = d - bo;\n            if (dot(dv, dv) > 1e-6) { edge = min(edge, dot(0.5 * (bo + d), normalize(dv))); }\n        }\n    }\n    let k = u32(hcell(bc, c.seed + 2u) * f32(n)) % max(n, 1u);\n    var col = stop_lin(f0, k) * (1.0 - i.p0.w * 0.55 * clamp(best * 1.6, 0.0, 1.0));\n    let seam = i.p0.z * 0.5;\n    if (seam > 0.0) {\n        let e = clamp(0.5 + (edge * sc - seam) * c.scale, 0.0, 1.0);\n        col = mix(i.c0.rgb, col, e);\n    }\n    return paint(col, m, i, px);\n}\n\nfn waves(i: Inst, c: Ctx, m: f32, px: vec2f) -> vec4f {\n    let f0 = u32(i.xf.x);\n    let n = u32(i.xf.y);\n    let ang = i.p0.w;\n    let dir = vec2f(-sin(ang), cos(ang));\n    let along = vec2f(cos(ang), sin(ang));\n    let ext = abs(c.half.x * dir.x) + abs(c.half.y * dir.y);\n    let ext2 = abs(c.half.x * along.x) + abs(c.half.y * along.y);\n    let v = dot(c.q, dir) / max(2.0 * ext, 1e-3) + 0.5;\n    let s = dot(c.q, along) / max(2.0 * ext2, 1e-3) + 0.5;\n    let aa = c.aa / max(2.0 * ext, 1e-3);\n    let soft = max(i.p1.x, aa);\n    let t = c.t * i.p0.z;\n    var col = stop_lin(f0, 0u);\n    for (var k = 1u; k < n; k++) {\n        let fk = f32(k);\n        let h = hcell(vec2i(i32(k), 3), c.seed);\n        let fq = i.p0.y * (0.8 + 0.4 * h);\n        let ph1 = fract(t * 0.2 * (1.0 + 0.3 * fk) + h);\n        let ph2 = fract(-t * 0.13) * TAU + 1.7 * fk;\n        let y = fk / f32(n) + i.p0.x * (0.7 * sin(TAU * (fq * s + ph1)) + 0.3 * sin(TAU * fq * 2.3 * s + ph2));\n        // The front band shades the one behind it just above its crest.\n        let shade = exp(-max(y - v, 0.0) / 0.025) * 0.18 * step(v, y);\n        col *= 1.0 - shade;\n        col = mix(col, stop_lin(f0, k), smoothstep(y - soft, y + soft, v));\n    }\n    return paint(col, m, i, px);\n}\n\nfn halftone(i: Inst, c: Ctx, m: f32, px: vec2f) -> vec4f {\n    let pitch = max(i.p0.z, 1.0);\n    let ang = i.p2.x;\n    let r = rot2(c.p - c.c, -ang) / pitch;\n    let base = floor(r - 0.5);\n    let kind = i32(i.p0.y + 0.5);\n    var ink = 0.0;\n    // The four nearest dots, so big dots merge across cell lines.\n    for (var y = 0; y <= 1; y++) {\n        for (var x = 0; x <= 1; x++) {\n            let cc = base + vec2f(f32(x), f32(y)) + 0.5;\n            let w = c.c + rot2(cc * pitch, ang);\n            let cov = 1.0 - tone_at(i, c, w, kind, i.p0.w);\n            let rad = sqrt(cov / PI) * 1.12;\n            let d = (length(r - cc) - rad) * pitch;\n            ink = max(ink, clamp(0.5 - d * c.scale, 0.0, 1.0));\n        }\n    }\n    return paint(mix(i.c1.rgb, i.c0.rgb, ink), m, i, px);\n}\n\nfn rune_shade(in: VOut) -> vec4f {\n    let i = inst_at();\n    let px = pixel(in);\n    let c = ctx(i, px);\n    let m = fill_mask(c, i.aux.x);\n    if (m <= 0.0) { return vec4f(0.0); }\n    switch c.variant {\n        case 0: { return liquid_metal(i, c, m, px); }\n        case 1: { return mesh_gradient(i, c, m, px); }\n        case 2: { return dither(i, c, m); }\n        case 3: { return grain_gradient(i, c, m, px); }\n        case 4: { return fluted(i, c, m, px); }\n        case 5: { return metaballs(i, c, m, px); }\n        case 6: { return swirl(i, c, m, px); }\n        case 7: { return voronoi(i, c, m, px); }\n        case 8: { return waves(i, c, m, px); }\n        case 9: { return halftone(i, c, m, px); }\n        default: { return plastic(i, c, m, px); }\n    }\n}\n";
